import HeroSectionV8 from "./hero-section-v8"

export default function Page() {
  return <HeroSectionV8 />
}

"use client"

import { useEffect, useState, type CSSProperties } from "react"

import { brands } from "../brands-section-v1/brands"
import {
  CAROUSEL_ENTER_ANIM_MS,
  CAROUSEL_EXIT_ANIM_MS,
  CAROUSEL_PAGE_SIZE,
  toCarouselColumn,
} from "./carousel-timing"
import { useBrandCarouselFlip } from "./use-brand-carousel-flip"
import HeroV8BrandCell from "./hero-v8-brand-cell"

const pages = [
  brands.slice(0, CAROUSEL_PAGE_SIZE),
  brands.slice(CAROUSEL_PAGE_SIZE, CAROUSEL_PAGE_SIZE * 2),
]

const carouselGridStyle = (): CSSProperties =>
  ({
    "--hero-v8-exit-duration": `${CAROUSEL_EXIT_ANIM_MS}ms`,
    "--hero-v8-enter-duration": `${CAROUSEL_ENTER_ANIM_MS}ms`,
  }) as CSSProperties

export default function HeroV8BrandCarousel() {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false)

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")

    const sync = () => {
      setPrefersReducedMotion(mq.matches)
    }

    sync()
    mq.addEventListener("change", sync)

    return () => {
      mq.removeEventListener("change", sync)
    }
  }, [])

  const { pageIndex, columnPhases, columnsOnNextPage } = useBrandCarouselFlip({
    pageCount: pages.length,
    prefersReducedMotion,
  })

  const nextPageIndex = (pageIndex + 1) % pages.length
  const isFlipping = columnPhases.some((phase) => phase !== "idle")

  return (
    <div
      className="grid w-full min-w-0 grid-cols-3 bg-[color-mix(in_oklab,var(--muted)_28%,var(--background))]"
      role="list"
      aria-label="Company logos"
      aria-live="polite"
      data-flipping={isFlipping ? "true" : undefined}
      style={carouselGridStyle()}
    >
      {Array.from({ length: CAROUSEL_PAGE_SIZE }, (_, columnIndex) => {
        const column = toCarouselColumn(columnIndex)
        const outgoing = pages[pageIndex]?.[columnIndex]
        const incoming = pages[nextPageIndex]?.[columnIndex]
        const motionPhase = prefersReducedMotion
          ? "idle"
          : columnPhases[columnIndex]

        if (!outgoing || !incoming) {
          return null
        }

        return (
          <HeroV8BrandCell
            key={`column-${column}`}
            column={column}
            phase={motionPhase}
            outgoing={outgoing}
            incoming={incoming}
            showIncoming={columnsOnNextPage[columnIndex] ?? false}
          />
        )
      })}
    </div>
  )
}

"use client"

import type { Brand } from "../brands-section-v1/brands"
import BrandLogo from "../brands-section-v1/brand-logo"
import type { ColumnMotionPhase } from "./use-brand-carousel-flip"
import type { CarouselColumn } from "./carousel-timing"

const heroV8LogoClass =
  "size-full min-h-0 min-w-0 [&_svg]:h-full [&_svg]:w-full [&_svg]:object-contain"

type HeroV8BrandCellProps = {
  column: CarouselColumn
  phase: ColumnMotionPhase
  outgoing: Brand
  incoming: Brand
  showIncoming: boolean
}

export default function HeroV8BrandCell({
  column,
  phase,
  outgoing,
  incoming,
  showIncoming,
}: HeroV8BrandCellProps) {
  const isFlipping = phase === "exit" || phase === "enter"

  return (
    <div
      role="listitem"
      className="flex h-16 min-h-16 min-w-0 items-center justify-center overflow-hidden px-1.5 py-3 sm:h-20 sm:min-h-20 sm:px-2.5 sm:py-5 md:px-3"
      data-column={column}
    >
      <div className="relative mx-auto flex h-6 w-full min-w-0 max-w-36 items-center justify-center sm:h-7 md:h-8">
        {isFlipping ? (
          <>
            <div
              className="hero-v8-proof__layer absolute inset-0 flex items-center justify-center opacity-100"
              data-phase={phase === "exit" ? "exit" : "idle"}
              aria-hidden={phase === "enter"}
            >
              <BrandLogo brand={outgoing} className={heroV8LogoClass} />
            </div>
            <div
              className="hero-v8-proof__layer absolute inset-0 flex items-center justify-center"
              data-phase={phase === "enter" ? "enter" : "idle"}
              aria-hidden={phase === "exit"}
            >
              <BrandLogo brand={incoming} className={heroV8LogoClass} />
            </div>
          </>
        ) : (
          <div
            className="hero-v8-proof__layer blur-0 absolute inset-0 flex translate-x-0 translate-y-0 items-center justify-center opacity-100"
            data-phase="idle"
          >
            <BrandLogo
              brand={showIncoming ? incoming : outgoing}
              className={heroV8LogoClass}
            />
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"

import {
  CAROUSEL_CYCLE_MS,
  CAROUSEL_ENTER_ANIM_MS,
  CAROUSEL_EXIT_ANIM_MS,
  CAROUSEL_HOLD_MS,
  CAROUSEL_PAGE_SIZE,
} from "./carousel-timing"

export type ColumnMotionPhase = "idle" | "exit" | "enter"

const IDLE_COLUMNS: ColumnMotionPhase[] = ["idle", "idle", "idle"]

type UseBrandCarouselFlipOptions = {
  pageCount: number
  prefersReducedMotion: boolean
}

export function useBrandCarouselFlip({
  pageCount,
  prefersReducedMotion,
}: UseBrandCarouselFlipOptions) {
  const [pageIndex, setPageIndex] = useState(0)
  const [columnPhases, setColumnPhases] =
    useState<ColumnMotionPhase[]>(IDLE_COLUMNS)
  const [columnsOnNextPage, setColumnsOnNextPage] = useState<boolean[]>(
    () => Array.from({ length: CAROUSEL_PAGE_SIZE }, () => false)
  )
  const timersRef = useRef<number[]>([])
  const intervalRef = useRef<number | undefined>(undefined)

  const clearTimers = useCallback(() => {
    for (const id of timersRef.current) {
      window.clearTimeout(id)
    }
    timersRef.current = []

    if (intervalRef.current !== undefined) {
      window.clearInterval(intervalRef.current)
      intervalRef.current = undefined
    }
  }, [])

  const schedule = useCallback((fn: () => void, delay: number) => {
    const id = window.setTimeout(fn, delay)
    timersRef.current.push(id)
    return id
  }, [])

  const setColumnPhase = useCallback(
    (columnIndex: number, phase: ColumnMotionPhase) => {
      setColumnPhases((current) => {
        const next = [...current]
        next[columnIndex] = phase
        return next
      })
    },
    []
  )

  const markColumnOnNextPage = useCallback((columnIndex: number) => {
    setColumnsOnNextPage((current) => {
      const next = [...current]
      next[columnIndex] = true
      return next
    })
  }, [])

  const resetColumnFlipState = useCallback(() => {
    setColumnPhases(IDLE_COLUMNS)
    setColumnsOnNextPage(
      Array.from({ length: CAROUSEL_PAGE_SIZE }, () => false)
    )
  }, [])

  const flipColumn = useCallback(
    (columnIndex: number, onDone: () => void) => {
      setColumnPhase(columnIndex, "exit")

      schedule(() => {
        setColumnPhase(columnIndex, "enter")

        schedule(() => {
          markColumnOnNextPage(columnIndex)
          setColumnPhase(columnIndex, "idle")
          onDone()
        }, CAROUSEL_ENTER_ANIM_MS)
      }, CAROUSEL_EXIT_ANIM_MS)
    },
    [markColumnOnNextPage, schedule, setColumnPhase]
  )

  const flip = useCallback(() => {
    if (pageCount <= 1) {
      return
    }

    if (prefersReducedMotion) {
      setPageIndex((current) => (current + 1) % pageCount)
      resetColumnFlipState()
      return
    }

    resetColumnFlipState()

    const runColumn = (columnIndex: number) => {
      if (columnIndex >= CAROUSEL_PAGE_SIZE) {
        setPageIndex((current) => (current + 1) % pageCount)
        resetColumnFlipState()
        return
      }

      flipColumn(columnIndex, () => {
        runColumn(columnIndex + 1)
      })
    }

    runColumn(0)
  }, [
    flipColumn,
    pageCount,
    prefersReducedMotion,
    resetColumnFlipState,
  ])

  useEffect(() => {
    clearTimers()

    schedule(() => {
      setPageIndex(0)
      resetColumnFlipState()
    }, 0)

    schedule(() => {
      flip()
      intervalRef.current = window.setInterval(flip, CAROUSEL_CYCLE_MS)
    }, CAROUSEL_HOLD_MS)

    return clearTimers
  }, [clearTimers, flip, resetColumnFlipState, schedule])

  const nextPageIndex = (pageIndex + 1) % pageCount

  const brandPageForColumn = useCallback(
    (columnIndex: number) => {
      const phase = columnPhases[columnIndex]

      if (phase === "exit") {
        return pageIndex
      }

      if (phase === "enter" || columnsOnNextPage[columnIndex]) {
        return nextPageIndex
      }

      return pageIndex
    },
    [columnPhases, columnsOnNextPage, nextPageIndex, pageIndex]
  )

  return {
    pageIndex,
    columnPhases,
    columnsOnNextPage,
    brandPageForColumn,
  }
}

.hero-v8-proof__layer[aria-hidden="true"] {
  visibility: hidden;
  pointer-events: none;
  animation: none !important;
  opacity: 0;
}

.hero-v8-proof__layer[data-phase="exit"] {
  will-change: opacity, transform, filter;
  animation: hero-v8-proof-out var(--hero-v8-exit-duration, 260ms)
    cubic-bezier(0.4, 0, 1, 1) forwards;
}

.hero-v8-proof__layer[data-phase="enter"] {
  opacity: 0;
  will-change: opacity, transform, filter;
  animation: hero-v8-proof-in var(--hero-v8-enter-duration, 280ms)
    cubic-bezier(0, 0, 0.2, 1) both;
}

.hero-v8-proof__layer[data-phase="idle"] {
  animation: none;
  filter: blur(0);
  transform: translate3d(0, 0, 0);
}

@keyframes hero-v8-proof-out {
  from {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
    filter: blur(0);
  }

  to {
    opacity: 0;
    transform: translate3d(10px, -4px, 0) scale(0.97);
    filter: blur(8px);
  }
}

@keyframes hero-v8-proof-in {
  from {
    opacity: 0;
    transform: translate3d(-12px, 6px, 0) scale(0.97);
    filter: blur(8px);
  }

  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
    filter: blur(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-v8-proof__layer[data-phase="exit"],
  .hero-v8-proof__layer[data-phase="enter"] {
    animation: none;
    opacity: 1;
    visibility: visible;
  }
}

.hero-v8-cta__dots {
  display: inline-flex;
  overflow: hidden;
  max-width: 0;
  opacity: 0;
  transition:
    max-width 0.3s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.2s ease;
}

.hero-v8-cta__dots span {
  line-height: 1;
  opacity: 0;
  transform: translateY(5px);
  transition:
    opacity 0.2s ease,
    transform 0.2s ease;
}

.group:hover .hero-v8-cta__dots,
.group:focus-visible .hero-v8-cta__dots {
  max-width: 1.1rem;
  opacity: 1;
}

.group:hover .hero-v8-cta__dots span,
.group:focus-visible .hero-v8-cta__dots span {
  opacity: 1;
  transform: translateY(0);
}

.group:hover .hero-v8-cta__dots span:nth-child(1),
.group:focus-visible .hero-v8-cta__dots span:nth-child(1) {
  transition-delay: 0.05s;
}

.group:hover .hero-v8-cta__dots span:nth-child(2),
.group:focus-visible .hero-v8-cta__dots span:nth-child(2) {
  transition-delay: 0.12s;
}

.group:hover .hero-v8-cta__dots span:nth-child(3),
.group:focus-visible .hero-v8-cta__dots span:nth-child(3) {
  transition-delay: 0.19s;
}

@keyframes hero-v8-cta-dot-bounce {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-3px);
  }
}

.group:hover .hero-v8-cta__dots span,
.group:focus-visible .hero-v8-cta__dots span {
  animation: hero-v8-cta-dot-bounce 0.55s ease-in-out infinite;
}

.group:hover .hero-v8-cta__dots span:nth-child(2),
.group:focus-visible .hero-v8-cta__dots span:nth-child(2) {
  animation-delay: 0.12s;
}

.group:hover .hero-v8-cta__dots span:nth-child(3),
.group:focus-visible .hero-v8-cta__dots span:nth-child(3) {
  animation-delay: 0.24s;
}

.hero-v8-cta__sweep {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    transparent 35%,
    color-mix(in oklab, var(--foreground) 12%, transparent) 50%,
    transparent 65%
  );
  transform: translateX(-120%);
  pointer-events: none;
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.group:hover .hero-v8-cta__sweep,
.group:focus-visible .hero-v8-cta__sweep {
  transform: translateX(120%);
}

.hero-v8-cta__secondary-text {
  letter-spacing: 0;
  transition: letter-spacing 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.group:hover .hero-v8-cta__secondary-text,
.group:focus-visible .hero-v8-cta__secondary-text {
  letter-spacing: 0.06em;
}

.hero-v8-cta__arrow-stack {
  position: relative;
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.hero-v8-cta__arrow {
  position: absolute;
  inset: 0;
  margin: auto;
  transition:
    opacity 0.25s ease,
    transform 0.35s cubic-bezier(0.34, 1.45, 0.64, 1);
}

.hero-v8-cta__arrow--lead {
  opacity: 1;
  transform: translateX(0);
}

.hero-v8-cta__arrow--trail-1,
.hero-v8-cta__arrow--trail-2 {
  opacity: 0;
  transform: translateX(-6px);
}

.group:hover .hero-v8-cta__arrow--lead,
.group:focus-visible .hero-v8-cta__arrow--lead {
  transform: translateX(5px);
}

.group:hover .hero-v8-cta__arrow--trail-1,
.group:focus-visible .hero-v8-cta__arrow--trail-1 {
  opacity: 0.45;
  transform: translateX(-1px);
  transition-delay: 0.04s;
}

.group:hover .hero-v8-cta__arrow--trail-2,
.group:focus-visible .hero-v8-cta__arrow--trail-2 {
  opacity: 0.2;
  transform: translateX(-5px);
  transition-delay: 0.08s;
}

@media (prefers-reduced-motion: reduce) {
  .hero-v8-cta__dots,
  .hero-v8-cta__dots span,
  .hero-v8-cta__sweep,
  .hero-v8-cta__secondary-text,
  .hero-v8-cta__arrow {
    transition: none !important;
    animation: none !important;
  }

  .group:hover .hero-v8-cta__dots,
  .group:focus-visible .hero-v8-cta__dots {
    max-width: none;
    opacity: 1;
  }

  .group:hover .hero-v8-cta__dots span,
  .group:focus-visible .hero-v8-cta__dots span {
    opacity: 1;
    transform: none;
  }

  .group:hover .hero-v8-cta__sweep,
  .group:focus-visible .hero-v8-cta__sweep {
    transform: none;
  }

  .group:hover .hero-v8-cta__secondary-text,
  .group:focus-visible .hero-v8-cta__secondary-text {
    letter-spacing: 0;
  }

  .group:hover .hero-v8-cta__arrow--lead,
  .group:focus-visible .hero-v8-cta__arrow--lead {
    transform: none;
  }
}
